static NJS_TEXNAME splash_texname[1] = {
    {NULL, 0, 0},
};
static NJS_TEXLIST splash_texlist = {splash_texname, 1};

static NJS_TEXANIM splash_cell = {
    (Sint16)SPLASH_ART_W,
    (Sint16)SPLASH_ART_H,
    (Sint16)(SPLASH_ART_W / 2U),
    (Sint16)(SPLASH_ART_H / 2U),
    0,
    0,
    SPLASH_UV_U2,
    SPLASH_UV_V2,
    0,
    0,
};

static NJS_SPRITE splash_sprite = {
    {SPLASH_CENTER_X, SPLASH_CENTER_Y, 0.0F},
    SPLASH_SCALE,
    SPLASH_SCALE,
    0,
    &splash_texlist,
    &splash_cell,
};

static Bool splash_loaded;

static void write_le16(Uint8 *dst, Uint16 value)
{
    dst[0] = (Uint8)(value & 0xffU);
    dst[1] = (Uint8)((value >> 8) & 0xffU);
}

static void write_le32(Uint8 *dst, Uint32 value)
{
    dst[0] = (Uint8)(value & 0xffU);
    dst[1] = (Uint8)((value >> 8) & 0xffU);
    dst[2] = (Uint8)((value >> 16) & 0xffU);
    dst[3] = (Uint8)((value >> 24) & 0xffU);
}

Uint32 sh4zam_splash_pvm_size(void)
{
    return SPLASH_PVM_BYTES;
}

Bool sh4zam_splash_build_pvm(Uint8 *out, Uint32 capacity)
{
    const Uint32 rle_size = (Uint32)sizeof(splash_rle);
    const Uint32 total_pixels = SPLASH_ART_W * SPLASH_ART_H;
    Uint32 src;
    Uint32 pixel;
    Uint8 *texels;

    if (out == NULL || capacity < SPLASH_PVM_BYTES) {
        return FALSE;
    }

    memset(out, 0, TEXEL_OFFSET);

    /* PVMH chunk: one texture entry carrying a global index. */
    out[0] = 'P';
    out[1] = 'V';
    out[2] = 'M';
    out[3] = 'H';
    write_le32(out + 4, PVMH_PAYLOAD);
    write_le16(out + 8, PVMH_GLOBALINDEX);
    write_le16(out + 10, 1U);
    write_le16(out + 12, 0U);
    write_le32(out + 14, SPLASH_GLOBAL_INDEX);

    /* PVRT chunk: 512x256 linear RGB565 rectangle texture. */
    out[PVRT_OFFSET + 0] = 'P';
    out[PVRT_OFFSET + 1] = 'V';
    out[PVRT_OFFSET + 2] = 'R';
    out[PVRT_OFFSET + 3] = 'T';
    write_le32(out + PVRT_OFFSET + 4, PVRT_HEAD + SPLASH_TEXEL_BYTES);
    write_le32(out + PVRT_OFFSET + 8,
               (Uint32)(NJD_TEXFMT_RGB_565 | NJD_TEXFMT_RECTANGLE));
    write_le16(out + PVRT_OFFSET + 12, (Uint16)SPLASH_TEX_W);
    write_le16(out + PVRT_OFFSET + 14, (Uint16)SPLASH_TEX_H);

    /* Decode the 384x256 indexed RLE bitmap into the left columns of the
     * 512x256 RGB565 surface and clear the right padding columns to black. */
    texels = out + TEXEL_OFFSET;
    src = 0;
    pixel = 0;
    while (src < rle_size && pixel < total_pixels) {
        Uint8 token = splash_rle[src++];
        Uint32 count;
        Uint32 i;

        if ((token & RLE_RUN_FLAG) != 0) {
            Uint8 index;
            Uint16 color;

            if (src >= rle_size) {
                return FALSE;
            }
            count = (Uint32)(token & RLE_COUNT_MASK) + RLE_RUN_MIN;
            index = splash_rle[src++];
            if (index >= SPLASH_PALETTE_SIZE || count > total_pixels - pixel) {
                return FALSE;
            }
            color = splash_palette[index];
            for (i = 0; i < count; i++) {
                Uint32 y = pixel / SPLASH_ART_W;
                Uint32 x = pixel % SPLASH_ART_W;

                write_le16(texels + (y * SPLASH_TEX_W + x) * 2U, color);
                pixel++;
            }
        } else {
            count = (Uint32)token + 1U;
            if (count > rle_size - src || count > total_pixels - pixel) {
                return FALSE;
            }
            for (i = 0; i < count; i++) {
                Uint8 index = splash_rle[src++];
                Uint32 y;
                Uint32 x;

                if (index >= SPLASH_PALETTE_SIZE) {
                    return FALSE;
                }
                y = pixel / SPLASH_ART_W;
                x = pixel % SPLASH_ART_W;
                write_le16(texels + (y * SPLASH_TEX_W + x) * 2U,
                           splash_palette[index]);
                pixel++;
            }
        }
    }

    if (pixel != total_pixels || src != rle_size) {
        return FALSE;
    }

    for (pixel = 0; pixel < SPLASH_ART_H; pixel++) {
        memset(texels + (pixel * SPLASH_TEX_W + SPLASH_ART_W) * 2U, 0,
               (SPLASH_TEX_W - SPLASH_ART_W) * 2U);
    }

    return TRUE;
}

Bool sh4zam_splash_load(void)
{
    Uint8 *archive;
    Bool ok;

    if (splash_loaded) {
        return TRUE;
    }

    archive = (Uint8 *)syMalloc(SPLASH_PVM_BYTES);
    if (archive == NULL) {
        return FALSE;
    }

    ok = sh4zam_splash_build_pvm(archive, SPLASH_PVM_BYTES);
    if (ok) {
        ok =
            texture_load_pvm_memory(archive, SPLASH_PVM_BYTES, &splash_texlist);
    }
    syFree(archive);
    splash_loaded = ok;
    return ok;
}

void sh4zam_splash_draw(void)
{
    if (!splash_loaded) {
        return;
    }
    njDrawSprite2D(&splash_sprite, 0, SPLASH_PRIORITY, SPLASH_ATTR);
}

void sh4zam_splash_release(void)
{
    if (!splash_loaded) {
        return;
    }
    texture_discard_pvm(&splash_texlist);
    splash_loaded = FALSE;
}
